<template>
  <section class="fragments-page">
    <header class="fragments-hero" data-scroll-reveal>
      <h1>{{ copy.heading }}</h1>
      <p class="fragments-intro">{{ copy.intro }}</p>
      <div class="fragments-controls" aria-label="Fragment tools">
        <div
          class="category-segmented"
          :class="{ life: activeCategory === 'life' }"
          role="group"
          aria-label="Fragment category"
        >
          <span class="category-thumb" aria-hidden="true"></span>
          <button
            type="button"
            class="category-option category-ideas"
            :aria-pressed="(activeCategory === 'ideas').toString()"
            @click="setCategory('ideas')"
          >
            <span>Ideas</span>
            <span class="category-count">{{ ideaCount }}</span>
          </button>
          <button
            type="button"
            class="category-option category-life"
            :aria-pressed="(activeCategory === 'life').toString()"
            @click="setCategory('life')"
          >
            <span>Life</span>
            <span class="category-count">{{ lifeCount }}</span>
          </button>
        </div>
        <label class="fragment-search" aria-label="Search fragments">
          <input
            v-model="searchQuery"
            class="fragment-search-input"
            type="search"
            autocomplete="off"
            spellcheck="false"
            placeholder="Search fragments"
            @keydown.esc.prevent="clearSearch"
          >
          <i class="fa fa-search fragment-search-icon" aria-hidden="true"></i>
        </label>
      </div>
    </header>

    <div class="fragment-list" data-scroll-group data-scroll-step="120">
      <article
        v-for="fragment in filteredFragments"
        :id="fragment.id"
        :key="fragment.id"
        class="fragment-card"
        :class="{ open: isOpen(fragment.id) }"
        data-scroll-reveal
      >
        <div
          class="fragment-summary"
          role="button"
          tabindex="0"
          :aria-expanded="isOpen(fragment.id).toString()"
          @click="toggleFragment(fragment.id)"
          @keydown.enter.prevent="toggleFragment(fragment.id)"
          @keydown.space.prevent="toggleFragment(fragment.id)"
        >
          <h2 v-html="highlightText(fragment.title)"></h2>
          <p class="fragment-teaser" v-html="highlightText(fragment.teaser)"></p>
          <span class="read-cue">
            {{ isOpen(fragment.id) ? copy.close : copy.read }}
            <i class="fas" :class="isOpen(fragment.id) ? 'fa-minus' : 'fa-plus'" aria-hidden="true"></i>
          </span>
        </div>

        <transition
          @before-enter="beforeFragmentExpand"
          @enter="enterFragmentExpand"
          @leave="leaveFragmentExpand"
        >
          <div v-if="isOpen(fragment.id)" class="fragment-body">
            <p
              v-for="(paragraph, index) in fragment.body"
              :key="`${fragment.id}-${index}`"
              v-html="highlightText(paragraph)"
            ></p>
          </div>
        </transition>
      </article>
    </div>
    <p v-if="searchActive && !filteredFragments.length" class="fragments-empty">
      No matching fragments.
    </p>
  </section>
</template>

<script>
import { animate } from 'motion';
import { fragments } from '../data/fragments';
import { settleScrollToId } from '../utils/anchorLanding';

function shuffleFragments(items) {
  const shuffled = [...items];

  for (let i = shuffled.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  return shuffled;
}

export default {
  name: 'FragmentsTab',
  data() {
    return {
      activeCategory: 'ideas',
      openIds: [],
      searchQuery: '',
      shuffledFragments: shuffleFragments(fragments)
    };
  },
  computed: {
    ideaFragments() {
      return this.shuffledFragments.filter((fragment) => fragment.category === 'ideas');
    },
    lifeFragments() {
      return this.shuffledFragments.filter((fragment) => fragment.category === 'life');
    },
    ideaCount() {
      return this.searchActive
        ? this.ideaFragments.filter((fragment) => this.fragmentMatches(fragment)).length
        : this.ideaFragments.length;
    },
    lifeCount() {
      return this.searchActive
        ? this.lifeFragments.filter((fragment) => this.fragmentMatches(fragment)).length
        : this.lifeFragments.length;
    },
    copy() {
      return {
        heading: 'Fragments',
        intro: 'Fragments is where I keep things I want to return to. Some are thoughts still taking shape. Others come from places, memories, conversations, or small things I notice in everyday life. I write them down while they are still on my mind.',
        read: 'Read',
        close: 'Close'
      };
    },
    filteredFragments() {
      const categoryFragments = this.activeCategory === 'life' ? this.lifeFragments : this.ideaFragments;
      if (this.searchActive) {
        return categoryFragments.filter((fragment) => this.fragmentMatches(fragment));
      }
      return categoryFragments;
    },
    searchActive() {
      return this.searchTerms.length > 0;
    },
    searchTerms() {
      return this.searchQuery
        .toLowerCase()
        .split(/[\s,.;:!?()[\]{}"']+/)
        .map((term) => term.trim())
        .filter((term) => term.length >= 2);
    }
  },
  watch: {
    '$route.hash'() {
      this.activateHashFragment();
    },
    searchQuery() {
      if (this.searchActive) {
        this.openIds = [];
      }
    }
  },
  created() {
    // The category must be switched and the card opened before it can be
    // scrolled into view; mounted() then owns the landing for this tab.
    this.activateHashFragment(false);
  },
  mounted() {
    this.activateHashFragment();
    window.addEventListener('hashchange', this.activateHashFragment);
    this._fragmentAnims = new Set();
  },
  unmounted() {
    window.removeEventListener('hashchange', this.activateHashFragment);
    if (this._fragmentAnims) {
      this._fragmentAnims.forEach((animation) => animation.stop());
      this._fragmentAnims.clear();
    }
  },
  methods: {
    // Fragment cards expand and collapse along the same path: height and
    // opacity move together on a critically-damped spring, so an interrupt
    // (rapid open/close) continues from the current on-screen size.
    beforeFragmentExpand(el) {
      el.style.height = '0px';
      el.style.overflow = 'hidden';
      el.style.opacity = '0';
    },
    enterFragmentExpand(el, done) {
      const reduceMotion = window.matchMedia
        && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (reduceMotion) {
        el.style.height = '';
        el.style.overflow = '';
        el.style.opacity = '';
        done();
        return;
      }
      const target = el.scrollHeight;
      const animation = animate(el, {
        height: [0, target],
        opacity: [0, 1],
      }, {
        type: 'spring',
        bounce: 0,
        duration: 0.35,
        onComplete: () => {
          el.style.height = '';
          el.style.overflow = '';
          if (this._fragmentAnims) this._fragmentAnims.delete(animation);
          done();
        },
      });
      if (this._fragmentAnims) this._fragmentAnims.add(animation);
    },
    leaveFragmentExpand(el, done) {
      const reduceMotion = window.matchMedia
        && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (reduceMotion) {
        el.style.height = '';
        el.style.overflow = '';
        el.style.opacity = '';
        done();
        return;
      }
      const from = el.scrollHeight;
      el.style.height = `${from}px`;
      // Force the browser to accept the explicit height before collapsing.
      void el.offsetHeight;
      const animation = animate(el, {
        height: [from, 0],
        opacity: [1, 0],
      }, {
        type: 'spring',
        bounce: 0,
        duration: 0.25,
        onComplete: () => {
          el.style.height = '';
          el.style.overflow = '';
          if (this._fragmentAnims) this._fragmentAnims.delete(animation);
          done();
        },
      });
      if (this._fragmentAnims) this._fragmentAnims.add(animation);
    },
    currentHashId() {
      const routeHash = this.$route && this.$route.hash ? this.$route.hash : '';
      const browserHash = typeof window !== 'undefined' ? window.location.hash : '';
      let raw = routeHash;

      // In hash-router URLs the browser hash can look like "#/fragments#entry-id".
      // Vue usually exposes the second hash as this.$route.hash, but parse it here too
      // so direct browser/hashchange paths are safe.
      if (!raw && browserHash.startsWith('#/')) {
        const secondHash = browserHash.indexOf('#', 1);
        if (secondHash >= 0) raw = browserHash.slice(secondHash);
      }
      if (!raw) raw = browserHash;
      if (!raw) return '';

      try {
        return decodeURIComponent(raw.replace(/^#/, ''));
      } catch (err) {
        return raw.replace(/^#/, '');
      }
    },
    fragmentById(id) {
      return fragments.find((fragment) => fragment.id === id);
    },
    escapeHtml(text) {
      return String(text == null ? '' : text)
        .split('&').join('&amp;')
        .split('<').join('&lt;')
        .split('>').join('&gt;')
        .split(String.fromCharCode(34)).join('&quot;')
        .split("'").join('&#39;');
    },
    escapeRegExp(text) {
      return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    },
    fragmentSearchText(fragment) {
      return [
        fragment.title,
        fragment.teaser,
        ...(Array.isArray(fragment.body) ? fragment.body : [])
      ].join(' ').toLowerCase();
    },
    fragmentMatches(fragment) {
      const terms = this.searchTerms;
      if (!terms.length) return false;
      const text = this.fragmentSearchText(fragment);
      return terms.every((term) => text.includes(term));
    },
    highlightText(text) {
      const escaped = this.escapeHtml(text);
      const terms = [...new Set(this.searchTerms)]
        .sort((a, b) => b.length - a.length)
        .map((term) => this.escapeRegExp(term));
      if (!terms.length) return escaped;

      const re = new RegExp(`(${terms.join('|')})`, 'gi');
      return escaped.replace(re, '<mark>$1</mark>');
    },
    clearSearch() {
      this.searchQuery = '';
    },
    activateHashFragment(shouldScroll = true) {
      const id = this.currentHashId();
      if (!id) return;

      const fragment = this.fragmentById(id);
      if (!fragment) return;

      if (fragment.category && this.activeCategory !== fragment.category) {
        this.activeCategory = fragment.category;
      }

      if (!this.openIds.includes(id)) {
        this.openIds = [id];
      }

      if (!shouldScroll) return;

      this.$nextTick(() => {
        this.scrollToHashFragment(id, 0);
      });
    },
    scrollToHashFragment(id, attempt = 0) {
      const el = document.getElementById(id);
      if (!el) {
        if (attempt < 20) {
          window.setTimeout(() => this.scrollToHashFragment(id, attempt + 1), 80);
        }
        return;
      }

      // The card body expands on a spring; wait for it to settle so the
      // landing position is final, then glide in like the other pages.
      window.setTimeout(() => {
        settleScrollToId(id);
        window.dispatchEvent(new Event('scroll'));
      }, 450);
    },
    setCategory(category) {
      if (this.activeCategory === category) return;
      this.activeCategory = category;
      this.openIds = [];
    },
    isOpen(id) {
      return this.openIds.includes(id);
    },
    toggleFragment(id) {
      if (this.isOpen(id)) {
        this.openIds = this.openIds.filter((openId) => openId !== id);
      } else {
        this.openIds = [...this.openIds, id];
      }
      this.$nextTick(() => window.dispatchEvent(new Event('scroll')));
    }
  }
};
</script>

