<script>
  import scrollRevealMixin from '../mixins/scrollRevealMixin';

  export default {
    name: 'AboutTab',
    mixins: [scrollRevealMixin],
    data() {
      return {
        scriptModule: null,
        photoLoaded: false,
        preview: '',
        previewStyle: null,
      };
    },
    async mounted() {
      if (this.$refs.photo && this.$refs.photo.complete) {
        this.photoLoaded = true;
      }

      this.scriptModule = await import('../assets/js/about.js');
      if (this.scriptModule && this.scriptModule.initScript) {
        this.scriptModule.initScript();
      }
      this._onPreviewDismiss = () => this.hidePreview();
      window.addEventListener('scroll', this._onPreviewDismiss, { passive: true });
      window.addEventListener('resize', this._onPreviewDismiss, { passive: true });
    },
    unmounted() {
      window.removeEventListener('scroll', this._onPreviewDismiss);
      window.removeEventListener('resize', this._onPreviewDismiss);
      if (this.scriptModule && this.scriptModule.cleanupScript) {
        this.scriptModule.cleanupScript();
      }
      this.scriptModule = null;
    },
    methods: {
      previewLabel(key) {
        return {
          cv: 'CV · Han-yu Wang',
          travels: 'Travels · Places that stayed with me',
          projects: 'Projects · Things I\'ve Built',
          fragments: 'Fragments · Thoughts and life',
        }[key] || 'Preview';
      },
      previewIframeSrc(key) {
        return {
          cv: '#/cv?preview=1',
          travels: '#/travels?preview=1',
          projects: '#/projects?preview=1',
          fragments: '#/fragments?preview=1',
        }[key] || null;
      },
      previewRoute(key) {
        return {
          cv: '/cv',
          travels: '/travels',
          projects: '/projects',
          fragments: '/fragments',
        }[key] || '/';
      },
      showPreview(key, event) {
        if (this._previewHideTimer) {
          clearTimeout(this._previewHideTimer);
          this._previewHideTimer = null;
        }
        const host = event && event.currentTarget;
        if (host) {
          const rect = host.getBoundingClientRect();
          const width = Math.min(430, window.innerWidth - 32);
          // Horizontal: pull the preview toward the page center, but never
          // detach it from the hovered element. A strip of the preview always
          // overlaps the host, so the window reads as belonging to the link
          // even when it sits near the middle of the screen.
          const minOverlap = Math.min(64, Math.round(width * 0.14));
          const centerLeft = (window.innerWidth - width) / 2;
          const minLeft = Math.max(16, rect.left + minOverlap - width);
          const maxLeft = Math.min(
            window.innerWidth - width - 16,
            rect.right - minOverlap
          );
          const left = minLeft <= maxLeft
            ? Math.max(minLeft, Math.min(centerLeft, maxLeft))
            : Math.max(16, Math.min(rect.left + rect.width / 2 - width / 2, window.innerWidth - width - 16));
          this.previewStyle = { top: '0px', left: `${left}px` };
          this.preview = key;
          this.$nextTick(() => {
            const el = document.querySelector('.page-preview');
            if (!el) return;
            const height = el.offsetHeight;
            const below = rect.bottom + 12;
            const fitsBelow = below + height <= window.innerHeight - 8;
            const top = fitsBelow
              ? below
              : Math.max(8, rect.top - height - 12);
            this.previewStyle = { top: `${top}px`, left: `${left}px` };
          });
          return;
        }
        this.preview = key;
      },
      hidePreview() {
        if (this._previewHideTimer) {
          clearTimeout(this._previewHideTimer);
        }
        // A short grace lets the pointer travel from the host into the
        // teleported preview before it closes.
        this._previewHideTimer = setTimeout(() => {
          this._previewHideTimer = null;
          this.preview = '';
        }, 120);
      },
      keepPreview() {
        if (this._previewHideTimer) {
          clearTimeout(this._previewHideTimer);
          this._previewHideTimer = null;
        }
      },
      dismissPreview() {
        if (this._previewHideTimer) {
          clearTimeout(this._previewHideTimer);
          this._previewHideTimer = null;
        }
        this.preview = '';
      },
      openSearchPalette() {
        window.dispatchEvent(new KeyboardEvent('keydown', {
          key: '/',
          bubbles: true,
          cancelable: true,
        }));
      },
    },
  }
</script>

